definitions.code:
const provider="Microsoft Graph";
const official="https://graph.microsoft.com";
const base=new URL(config.baseUrl??official);
if(base.href!==official+'/'){if(base.protocol!=='http:'||!['127.0.0.1','[::1]'].includes(base.hostname)||base.username||base.password||base.pathname!=='/'||base.search||base.hash)throw new Error('Only explicit loopback HTTP mock baseUrl is permitted');}
const token=context.secrets.get(config.accessTokenSecret??"GRAPH_ACCESS_TOKEN");
const segment=v=>{if(v===undefined||v===null||String(v).length===0||String(v).length>500)throw new Error('Missing or oversized provider identifier');return encodeURIComponent(String(v));};
const safeCode=x=>String(x??'provider_error').replace(/[^a-zA-Z0-9_.-]/g,'').slice(0,100);
async function request(path,method='GET',body,read=true){
