 const retries=read?(config.readRetries??2):0;if(!Number.isInteger(retries)||retries<0||retries>3)throw new Error('Invalid readRetries');
 for(let attempt=0;;attempt++){
  let response;try{response=await fetch(url,{method,headers:{Authorization:'Bearer '+token,'Content-Type':'application/json'},...(body===undefined?{}:{body:JSON.stringify(body)}),redirect:'error',signal:AbortSignal.timeout(timeoutMs)});}catch(error){throw new Error(provider+' network/timeout failure'+(read?'':' - external completion uncertain'));}
